import { createSignal, onMount, Show, type JSX } from 'solid-js'
import { LensDashboard } from './LensDashboard'
import { parseDocument, type DashboardDocument } from './contract'
import fixture from '../fixtures/report-card.json'
import type { LensThemeMode } from './runtime'
import type { HostPanelRendererProps } from './panels/hostRenderers'
import type { ReportPlacementAction, ReportPlacementHost } from './reports/placementHost'

// Generated by `go run ./cmd/lens-report-example --card`: one report opened on
// its own and the same report on a dashboard beside a host-rendered, a deleted
// and a forbidden placement.

/** A synthetic host view: the host owns the drawing, the SDK the card around it. */
function LegacyBars(props: HostPanelRendererProps) {
  const options = () => (props.options ?? {}) as { field?: string; label?: string }
  const index = (name: string | undefined) => props.frame.data?.columns.findIndex((column) => column.name === name) ?? -1
  const rows = () => props.frame.data?.rows ?? []
  const max = () => Math.max(1, ...rows().map((row) => Number(row[index(options().field)]) || 0))
  return (
    <ul class="lens:m-0 lens:flex lens:list-none lens:flex-col lens:gap-2 lens:p-4" data-testid="legacy-bars">
      {rows().map((row) => {
        const value = Number(row[index(options().field)]) || 0
        return (
          <li class="lens:flex lens:items-center lens:gap-2 lens:text-base lens:text-strong">
            <span class="lens:w-10">{String(row[index(options().label)])}</span>
            <span style={{ display: 'inline-block', height: '12px', width: `${(value / max()) * 160}px`, background: 'var(--lens-accent-600)', 'border-radius': '2px' }} />
            <span>{value}</span>
          </li>
        )
      })}
    </ul>
  )
}

function storyHost(record: (message: string) => void): ReportPlacementHost {
  const action = (name: ReportPlacementAction) => (id: string) => record(`${name} ${id}`)
  return {
    capabilities: (id) => id === 'legacy' ? { drill: false, save: false, export: true } : { drill: true, save: true, export: true },
    actions: { open: action('open'), edit: action('edit'), configure: action('configure'), copy: action('copy'), remove: action('remove') },
  }
}

function Card(props: {
  theme: LensThemeMode
  document: DashboardDocument
  renderers?: boolean
  host?: ReportPlacementHost
  fetcher?: typeof fetch
  after?: () => void
}) {
  const [log, setLog] = createSignal('')
  onMount(() => props.after?.())
  return (
    <div class="lens-root" data-theme={props.theme}>
      <LensDashboard
        initialDocument={props.document}
        theme={props.theme}
        fetcher={props.fetcher}
        reportPlacementHost={props.host ?? storyHost(setLog)}
        renderers={props.renderers === false ? undefined : { 'legacy-bars': LegacyBars }}
      />
      <Show when={log()}><p data-testid="report-card-host-log" role="status">{log()}</p></Show>
    </div>
  )
}

const embedded = () => parseDocument(structuredClone(fixture.embedded))
const standalone = () => parseDocument(structuredClone(fixture.standalone))

export const EmbeddedLight = () => <Card theme="light" document={embedded()} />
export const EmbeddedDark = () => <Card theme="dark" document={embedded()} />
export const StandaloneLight = () => <Card theme="light" document={standalone()} />
export const StandaloneDark = () => <Card theme="dark" document={standalone()} />
export const CompatibilityLight = () => <Card theme="light" document={embedded()} renderers={false} />
export const CompatibilityDark = () => <Card theme="dark" document={embedded()} renderers={false} />

const openMenu = () => requestAnimationFrame(() => {
  globalThis.document.querySelector<HTMLButtonElement>('[data-testid="report-menu-revenue"]')?.click()
})
export const MenuOpenLight = () => <Card theme="light" document={embedded()} after={openMenu} />
export const MenuOpenDark = () => <Card theme="dark" document={embedded()} after={openMenu} />

/**
 * The card's table is loaded on its own and fails until the reader retries
 * this card; the chart beside it loads normally.
 */
function failingDocument(): { document: DashboardDocument; fetcher: typeof fetch } {
  const document = embedded()
  document.endpoints.panel = '/lens/panel'
  const frames = fixture.embedded.frames as Record<string, unknown>
  const deferred = new Map<string, unknown>()
  for (const panel of document.panels) {
    if (panel.id !== 'revenue::panel:table' && panel.id !== 'revenue::panel:channels') continue
    panel.deferred = true
    deferred.set(panel.id, frames[panel.frame])
    delete document.frames[panel.frame]
  }
  let attempts = 0
  const fetcher: typeof fetch = (_input, init) => {
    const body = JSON.parse(init?.body as string) as { panels: Array<{ panelId: string }> }
    const events = body.panels.map(({ panelId }) => {
      const fail = panelId === 'revenue::panel:table' && attempts === 0
      return { panelId, result: fail
        ? { error: { error: 'internal', message: 'synthetic failure' } }
        : { frames: { primary: deferred.get(panelId) }, calculation: { durationMs: 12, cacheHit: false, calculatedAt: '2026-10-12T06:00:00Z' } } }
    })
    if (body.panels.some(({ panelId }) => panelId === 'revenue::panel:table')) attempts += 1
    return Promise.resolve(new Response(`${[...events, { complete: true }].map((event) => JSON.stringify(event)).join('\n')}\n`, {
      status: 200, headers: { 'Content-Type': 'application/x-ndjson' },
    }))
  }
  return { document, fetcher }
}

function Failing(props: { theme: LensThemeMode }): JSX.Element {
  const { document, fetcher } = failingDocument()
  return <Card theme={props.theme} document={document} fetcher={fetcher} />
}
export const CardRetryLight = () => <Failing theme="light" />
export const CardRetryDark = () => <Failing theme="dark" />
